items.plantuml_diagram:
@startuml
start
:Employee enters email and password;
if (Both fields present?) then (yes)
  :Disable button and send POST /api/auth/login;
  if (Credentials valid?) then (yes)
    :Issue signed token and store securely;
    :Open My incidents screen;
  else (no)
    :Show generic error message;
  endif
else (no)
  :Show field-level validation errors;
endif
stop
@enduml

@startuml
start
:Employee selects Sign out;
:Delete locally stored token;
:Block access to protected screens;
:Return to Sign in screen;
stop
@enduml

@startuml
start
:Request owned incidents via GET /api/incidents;
if (Request succeeded?) then (yes)
  if (Any incidents found?) then (yes)
    :Show list ordered newest first;
  else (no)
    :Show empty state;
  endif
else (no)
  :Show error state with retry path;
endif
stop
@enduml

@startuml
start
:Employee selects a status filter;
if (Filter is All?) then (yes)
  :Show all owned incidents;
else (no)
  :Show only owned incidents with the selected status;
endif
stop
@enduml

@startuml
start
:Employee fills title, description, category, priority;
:Selects Save;
if (Form valid on client and server?) then (yes)
  :Disable save to prevent duplicate submission;
  :POST /api/incidents;
  :Create incident in Pending status owned by the employee;
  :Return to list and show confirmation;
else (no)
  :Show validation errors next to fields;
endif
stop
@enduml

@startuml
start
:Employee opens an incident;
:GET /api/incidents/{id};
if (Incident exists and is owned by requester?) then (yes)
  :Show incident data and history timeline;
else (no)
  :Return safe response without leaking information;
endif
:Navigate back to incident list;
stop
@enduml

@startuml
start
:Support agent calls PATCH /api/incidents/{id}/status;
if (Actor has support role?) then (yes)
  if (Transition is Pending to In progress or In progress to Resolved?) then (yes)
    :Update incident status;
    :Record history entry with previous status, new status, date, actor;
  else (no)
    :Reject invalid or backwards transition;
  endif
else (no)
  :Return forbidden response;
endif
stop
@enduml

@startuml
start
:Operations calls GET /health;
:Return health status without sensitive details;
stop
@enduml

@startuml
start
:Start development seed;
if (Environment is development or demonstration?) then (yes)
  if (DEMO_EMPLOYEE_PASSWORD and DEMO_SUPPORT_PASSWORD set?) then (yes)
    :Create employee, support agent, and three incidents with history;
    :Skip records that already exist (idempotent);
  else (no)
    :Fail with clear message;
  endif
else (no)
  :Do not create demo accounts;
endif
stop
@enduml

flows.plantuml_diagram:
@startuml
start
:Development seed creates demo accounts (env-supplied passwords);
:Employee opens app and enters email and password;
:Email normalized and validated;
if (Rate limit exceeded?) then (yes)
  :Reject with generic message;
else (no)
  :POST /api/auth/login with credentials;
  if (Credentials valid?) then (yes)
    :Issue signed expiring token;
    :Store token in Keystore-backed storage;
    :Open My incidents screen;
  else (no)
    :Show generic failure message;
  endif
endif
stop
@enduml

@startuml
start
:Employee opens New incident form;
:Enters title, description, category, priority;
if (Validation passes on client and server?) then (yes)
  :Block duplicate submissions;
  :POST /api/incidents;
  :Create incident in Pending status owned by employee;
  :Return to list with confirmation;
else (no)
  :Show errors next to corresponding fields;
endif
stop
@enduml

@startuml
start
:Employee opens My incidents;
:GET /api/incidents (owner-scoped, newest first);
if (Request failed?) then (yes)
  :Show recoverable error with retry;
else (no)
  if (List empty?) then (yes)
    :Show empty state;
  else (no)
    :Show list with loading/content states;
    :Employee selects status filter;
    :Show matching owned incidents only;
    :Employee opens an incident;
    :GET /api/incidents/{id} as owner;
    :Show details and status history timeline;
  endif
endif
stop
@enduml

@startuml
start
:Actor calls PATCH /api/incidents/{id}/status;
if (Actor has support role?) then (yes)
  if (Transition valid and forward?) then (yes)
    :Update incident status;
    :Record immutable history (previous, new, date, actor);
    :Owner later sees updated status in list and details;
  else (no)
    :Reject invalid transition;
  endif
else (no)
  :Return forbidden response;
endif
stop
@enduml

@startuml
start
:Employee signs in and receives token;
:Token stored in Keystore-backed storage;
:Employee works with incidents;
:Employee selects Sign out;
:Delete locally stored token;
:Protected screens no longer accessible;
stop
@enduml

@startuml
start
:Run reproducible migrations on PostgreSQL;
if (Environment is development or demonstration?) then (yes)
  if (DEMO passwords present in env?) then (yes)
    :Seed employee, support agent, three incidents, history;
  else (no)
    :Fail with clear message;
  endif
else (no)
  :Skip seeding;
endif
:Verify GET /health responds;
stop
@enduml
